  (2026, 'OK', 'Oklahoma Tuition Aid Grant (OTAG)', 'priority_deadline', 'wording', NULL, '"For best consideration, you should complete and submit the FAFSA to the federal student aid application system as soon as possible after the application becomes available. IT IS IMPORTANT TO APPLY EARLY."', 'Oklahoma State Regents for Higher Education (OKcollegeStart)', (SELECT id FROM external_documents WHERE url = 'https://www.okcollegestart.org/Financial_Aid_Planning/Oklahoma_Grants/Oklahoma_Tuition_Aid_Grant.aspx'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'OK', 'Oklahoma''s Promise', 'final_deadline', 'wording', NULL, '"Application Deadlines: June 30 - 8th-11th graders (recommended deadline); Dec. 31 - 12th graders (electronic submission or postmark required). All applications must be received prior to the student''s official date of high school graduation."', 'Oklahoma State Regents for Higher Education', (SELECT id FROM external_documents WHERE url = 'https://www.okhighered.org/okpromise/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'OR', 'Oregon Opportunity Grant', 'priority_deadline', 'wording', NULL, '"Submit a FAFSA or ORSAA as soon as possible after October 1 each year ... Awards are first-come, first-served until funds are depleted."', 'Oregon Student Aid', (SELECT id FROM external_documents WHERE url = 'https://oregonstudentaid.gov/grants/oregon-opportunity-grant/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'OR', 'Oregon Promise Grant (renewal)', 'final_deadline', 'date', DATE '2026-06-01', '"Students who are receiving the grant in the current academic year (2025-26) must have submitted the 2026-27 FAFSA or ORSAA by June 1, 2026 to be considered for the upcoming year."', 'Oregon Student Aid', (SELECT id FROM external_documents WHERE url = 'https://oregonstudentaid.gov/grants/oregon-promise-grant/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'OR', 'Oregon Promise Grant', 'final_deadline', 'wording', NULL, '"The Oregon Promise Grant has rolling deadlines based on when the student graduates ... Students who graduate between July 1, 2026 and June 30, 2027 can start applying in October 2026."', 'Oregon Student Aid', (SELECT id FROM external_documents WHERE url = 'https://oregonstudentaid.gov/grants/oregon-promise-grant/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'PA', 'PA State Grant - first-time applicants at a 2-year private college or other college/university (degree or college-transferable program), and ALL renewal applicants', 'final_deadline', 'date', DATE '2026-05-01', '"May 1, prior to the academic year"', 'Pennsylvania Higher Education Assistance Agency', (SELECT id FROM external_documents WHERE url = 'https://www.pheaa.org/grants/state-grant-program/apply-renew'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'PA', 'PA State Grant - first-time applicants at a community college, designated PA Open-Admission institution, business/trade/technical school, hospital school of nursing, or a non-transferable 2-year program', 'final_deadline', 'date', DATE '2026-08-01', '"August 1, prior to the academic year ... you must submit the FAFSA by August 1."', 'Pennsylvania Higher Education Assistance Agency', (SELECT id FROM external_documents WHERE url = 'https://www.pheaa.org/grants/state-grant-program/apply-renew'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'PA', 'PA Summer Grant', 'final_deadline', 'wording', NULL, '"September 1, for the summer period you are attending - You must submit the online PA Summer Grant application."', 'Pennsylvania Higher Education Assistance Agency', (SELECT id FROM external_documents WHERE url = 'https://www.pheaa.org/grants/state-grant-program/apply-renew'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'PA', 'PA State Grant - first-time applicants at a 2-year private college or other college/university (degree or college-transferable program), and ALL renewal applicants', 'final_deadline', 'date', DATE '2027-05-01', '"May 1, prior to the academic year"', 'Pennsylvania Higher Education Assistance Agency', (SELECT id FROM external_documents WHERE url = 'https://www.pheaa.org/grants/state-grant-program/apply-renew'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'PA', 'PA State Grant - first-time applicants at a community college, designated PA Open-Admission institution, business/trade/technical school, hospital school of nursing, or a non-transferable 2-year program', 'final_deadline', 'date', DATE '2027-08-01', '"August 1, prior to the academic year ... you must submit the FAFSA by August 1."', 'Pennsylvania Higher Education Assistance Agency', (SELECT id FROM external_documents WHERE url = 'https://www.pheaa.org/grants/state-grant-program/apply-renew'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'RI', 'Rhode Island Promise Scholarship', 'final_deadline', 'wording', NULL, 'The student must complete the FAFSA and any required FAFSA verification or other financial aid forms by the deadline prescribed by CCRI. No statewide date is published; the Community College of Rhode Island sets it.', 'Rhode Island Office of the Postsecondary Commissioner', (SELECT id FROM external_documents WHERE url = 'https://www.riopc.edu/rhode-island-promise-scholarship/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'SC', 'SC Need-based Grant; SC Lottery Tuition Assistance', 'final_deadline', 'none', NULL, '"The financial aid office on each eligible state public college campus administers the South Carolina Need-Based Grant program."', 'South Carolina Commission on Higher Education', (SELECT id FROM external_documents WHERE url = 'https://www.che.sc.gov/students-families-and-military/scholarships-and-grants-sc-residents'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'SD', 'South Dakota state aid', 'final_deadline', 'none', NULL, '"Students are encouraged to complete the FAFSA as soon as possible after it becomes available ... Many colleges have priority deadlines."', 'South Dakota Board of Regents / Our Dakota Dreams', (SELECT id FROM external_documents WHERE url = 'https://ourdakotadreams.com/paying-for-college/financial-aid/completing-the-fafsa/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'TN', 'Tennessee HOPE Scholarship (TELS)', 'final_deadline', 'wording', NULL, '"Application Deadlines: Fall Semester 09/01; Spring Semester 03/01; Summer Semester 05/01."', 'Tennessee Student Assistance Corporation', (SELECT id FROM external_documents WHERE url = 'http://collegefortn.org/tennessee-hope-scholarship/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'TN', 'Tennessee Student Assistance Award (TSAA)', 'final_deadline', 'date', DATE '2026-04-01', '"Apply by completing the Free Application for Federal Student Aid (FAFSA) by April 1."', 'Tennessee Student Assistance Corporation', (SELECT id FROM external_documents WHERE url = 'http://collegefortn.org/tennessee-financial-aid/tennessee-student-assistance-award/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'TN', 'Tennessee Student Assistance Award (TSAA)', 'priority_deadline', 'wording', NULL, '"To receive priority consideration, students are strongly encouraged to submit a FAFSA as soon as possible after October 1 each year."', 'Tennessee Student Assistance Corporation', (SELECT id FROM external_documents WHERE url = 'http://collegefortn.org/tennessee-financial-aid/tennessee-student-assistance-award/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'TN', 'Tennessee Promise', 'final_deadline', 'date', DATE '2027-04-01', '"High School students will be required to complete the Tennessee Promise application in the THEC Student Portal by November 2, 2026 and complete the FAFSA by April 1, 2027."', 'Tennessee Student Assistance Corporation', (SELECT id FROM external_documents WHERE url = 'http://collegefortn.org/tennessee-promise-scholarship/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'TN', 'Tennessee Promise (state application)', 'final_deadline', 'date', DATE '2026-11-02', '"High School students will be required to complete the Tennessee Promise application in the THEC Student Portal by November 2, 2026 and complete the FAFSA by April 1, 2027."', 'Tennessee Student Assistance Corporation', (SELECT id FROM external_documents WHERE url = 'http://collegefortn.org/tennessee-promise-scholarship/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'TN', 'Tennessee Student Assistance Award (TSAA)', 'final_deadline', 'date', DATE '2027-04-01', '"Apply by completing the Free Application for Federal Student Aid (FAFSA) by April 1."', 'Tennessee Student Assistance Corporation', (SELECT id FROM external_documents WHERE url = 'http://collegefortn.org/tennessee-financial-aid/tennessee-student-assistance-award/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'TX', 'TEXAS Grant and other state financial aid', 'priority_deadline', 'date', DATE '2026-01-15', '"General Academic Teaching Institutions (GATIs) in Texas ... must publicize and use January 15 as the state priority application deadline."', 'Texas Higher Education Coordinating Board', (SELECT id FROM external_documents WHERE url = 'https://reportcenter.highered.texas.gov/agency-publication/guidelines-manuals/fiscal-year-2027-state-financial-aid-guidelines/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'UT', 'Utah Promise Grant', 'final_deadline', 'wording', NULL, '"Complete a FAFSA. Demonstrate financial need."', 'Utah System of Higher Education', (SELECT id FROM external_documents WHERE url = 'https://ushe.edu/utah-promise-grant/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'UT', 'Utah Opportunity Scholarship', 'final_deadline', 'date', DATE '2027-03-18', '"Final Deadline: March 18, 2027"', 'Utah System of Higher Education', (SELECT id FROM external_documents WHERE url = 'https://ushe.edu/state-scholarships-aid/opportunity-scholarship/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'UT', 'Utah Opportunity Scholarship', 'priority_deadline', 'date', DATE '2027-01-29', '"Priority Deadline: January 29, 2027"', 'Utah System of Higher Education', (SELECT id FROM external_documents WHERE url = 'https://ushe.edu/state-scholarships-aid/opportunity-scholarship/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'VA', 'Virginia Commonwealth Award; Virginia Guaranteed Assistance Program; Two-Year College Transfer Grant', 'final_deadline', 'wording', NULL, '"This page provides a list of financial aid deadlines for Virginia''s public and private institutions participating in state financial aid programs. Please check with your preferred institutions'' financial aid offices for updates, details on priority versus final application deadlines."', 'State Council of Higher Education for Virginia', (SELECT id FROM external_documents WHERE url = 'https://www.schev.edu/financial-aid/financial-aid-deadlines'), (SELECT id FROM external_documents WHERE url = 'https://web.archive.org/web/20260831060713/https://www.schev.edu/financial-aid/financial-aid-deadlines'), DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'VA', 'Virginia Tuition Assistance Grant (VTAG)', 'final_deadline', 'date', DATE '2026-12-01', '"Applications submitted after September 15, but no later than December 1, will be considered for an award only if funds are available."', 'State Council of Higher Education for Virginia', (SELECT id FROM external_documents WHERE url = 'https://www.schev.edu/financial-aid/financial-aid/federal-state-financial-aid/virginia-tuition-assistance-grant-program'), (SELECT id FROM external_documents WHERE url = 'https://web.archive.org/web/20251223134414/https://www.schev.edu/financial-aid/financial-aid/federal-state-financial-aid/virginia-tuition-assistance-grant-program'), DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'VA', 'Virginia Tuition Assistance Grant (VTAG)', 'priority_deadline', 'date', DATE '2026-09-15', '"Completed applications must be submitted to the financial aid office of the institution on, or before, September 15 prior to the fall semester of enrollment."', 'State Council of Higher Education for Virginia', (SELECT id FROM external_documents WHERE url = 'https://www.schev.edu/financial-aid/financial-aid/federal-state-financial-aid/virginia-tuition-assistance-grant-program'), (SELECT id FROM external_documents WHERE url = 'https://web.archive.org/web/20251223134414/https://www.schev.edu/financial-aid/financial-aid/federal-state-financial-aid/virginia-tuition-assistance-grant-program'), DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'VA', 'Virginia Tuition Assistance Grant (VTAG)', 'priority_deadline', 'date', DATE '2027-09-15', '"Completed applications must be submitted to the financial aid office of the institution on, or before, September 15 prior to the fall semester of enrollment."', 'State Council of Higher Education for Virginia', (SELECT id FROM external_documents WHERE url = 'https://www.schev.edu/financial-aid/financial-aid/federal-state-financial-aid/virginia-tuition-assistance-grant-program'), (SELECT id FROM external_documents WHERE url = 'https://web.archive.org/web/20251223134414/https://www.schev.edu/financial-aid/financial-aid/federal-state-financial-aid/virginia-tuition-assistance-grant-program'), DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'VT', 'Vermont Grant', 'priority_deadline', 'wording', NULL, '"applications are considered on a first-come, first-served basis as long as funding is available"', 'Vermont Student Assistance Corporation (VSAC)', (SELECT id FROM external_documents WHERE url = 'https://www.vsac.org/pay/student-aid-options/grants'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'WA', 'Washington College Grant (WA Grant)', 'final_deadline', 'wording', NULL, 'WSAC publishes no deadline: it''s never too early to plan ahead or too late to apply. The WA Grant is an entitlement for eligible students, and the WASFA is the route for people who do not file a FAFSA.', 'Washington Student Achievement Council', (SELECT id FROM external_documents WHERE url = 'https://wsac.wa.gov/wcg'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'WI', 'Wisconsin Grant (WG-UW, WG-TC, WG-TR, WG-PNP)', 'priority_deadline', 'wording', NULL, '"Application Priority Date by which students should apply for financial aid to receive maximum eligibility."', 'Wisconsin Higher Educational Aids Board (HEAB)', (SELECT id FROM external_documents WHERE url = 'https://heab.wi.gov/appinfo.html'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'WV', 'WV Higher Education Grant', 'final_deadline', 'date', DATE '2026-04-15', '"Complete the Free Application for Federal Student Aid (FAFSA) by April 15 each year."', 'West Virginia Higher Education Policy Commission', (SELECT id FROM external_documents WHERE url = 'https://www.cfwv.com/financial-aid/wv-higher-education-grant/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'WV', 'PROMISE Scholarship', 'final_deadline', 'date', DATE '2027-03-01', '"The class of 2027 should apply by completing the Promise Scholarship application and FAFSA by the March 1, 2027, deadline."', 'West Virginia Higher Education Policy Commission', (SELECT id FROM external_documents WHERE url = 'https://www.cfwv.com/financial-aid/promise-scholarship/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2027, 'WV', 'WV Higher Education Grant', 'final_deadline', 'date', DATE '2027-04-15', '"Complete the Free Application for Federal Student Aid (FAFSA) by April 15 each year."', 'West Virginia Higher Education Policy Commission', (SELECT id FROM external_documents WHERE url = 'https://www.cfwv.com/financial-aid/wv-higher-education-grant/'), NULL, DATE '2026-09-14', DATE '2027-09-14'),
  (2026, 'WY', 'Hathaway Scholarship (need-based component)', 'final_deadline', 'none', NULL, 'Wyoming Department of Education publishes no state FAFSA deadline for this program; the college sets it.', 'Wyoming Department of Education', (SELECT id FROM external_documents WHERE url = 'https://hathawayscholarship.org/resources/paying/fafsa/'), NULL, DATE '2026-09-14', DATE '2027-09-14')
